<?php require 'config.php'; if(!isset($_SESSION['user'])){header('Location:login.php');exit;} $id=(int)($_GET['id']??0); $st=$pdo->prepare('SELECT * FROM projects WHERE id=?'); $st->execute([$id]); $p=$st->fetch(); if(!$p){ die('Проект не найден'); } $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $title=trim($_POST['title']??''); $description=trim($_POST['description']??''); $link=trim($_POST['link']??''); $tag=$_POST['tag']??'other'; $imageName=$p['image']; if(!empty($_FILES['image']['name'])){ $allowed=['jpg','jpeg','png','webp','gif']; $ext=strtolower(pathinfo($_FILES['image']['name'], PATHINFO_EXTENSION)); if(!in_array($ext,$allowed)){ $err='Недопустимый формат изображения'; } else { if(!is_dir(__DIR__.'/uploads')){ mkdir(__DIR__.'/uploads',0775,true);} $new=uniqid('img_').'.'+$ext; } } if(!empty($_FILES['image']['name'])){ $ext=strtolower(pathinfo($_FILES['image']['name'], PATHINFO_EXTENSION)); $new='img_'+uniqid()+'.'+$ext; } if(!empty($_FILES['image']['name'])){ $ext=strtolower(pathinfo($_FILES['image']['name'], PATHINFO_EXTENSION)); $new=uniqid('img_').'.'.$ext; if(move_uploaded_file($_FILES['image']['tmp_name'], __DIR__.'/uploads/'.$new)){ if(!empty($imageName) && file_exists(__DIR__.'/uploads/'.$imageName)) @unlink(__DIR__.'/uploads/'.$imageName); $imageName=$new; } else { $err='Не удалось загрузить файл'; } } if(!$err){ $upd=$pdo->prepare('UPDATE projects SET title=?,description=?,image=?,link=?,tag=? WHERE id=?'); $upd->execute([$title,$description,$imageName,$link,$tag,$id]); header('Location: projects.php'); exit; } } ?>
<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Редактировать проект</title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css"><link rel="stylesheet" href="style.css"></head><body><?php include 'navbar.php'; ?><div class="container mt-4 fade-in"><h2>Редактировать проект</h2><?php if(!empty($err)):?><div class="alert alert-danger"><?= $err ?></div><?php endif; ?><form method="post" enctype="multipart/form-data" class="row g-3"><div class="col-12"><label class="form-label">Название</label><input name="title" class="form-control" value="<?= htmlspecialchars($p['title']) ?>" required></div><div class="col-12"><label class="form-label">Описание</label><textarea name="description" rows="4" class="form-control" required><?= htmlspecialchars($p['description']) ?></textarea></div><div class="col-md-6"><label class="form-label">Ссылка</label><input name="link" class="form-control" value="<?= htmlspecialchars($p['link']) ?>"></div><div class="col-md-6"><label class="form-label">Тег</label><select name="tag" class="form-select"><option value="web" <?= $p['tag']==='web'?'selected':'' ?>>Web</option><option value="3D" <?= $p['tag']==='3D'?'selected':'' ?>>3D</option><option value="other" <?= $p['tag']==='other'?'selected':'' ?>>Другое</option></select></div><div class="col-12"><label class="form-label">Изображение (оставьте пустым, чтобы не менять)</label><div id="drop-area" class="border border-primary p-4 text-center rounded bg-dark text-light"><p class="mb-2">Перетащите картинку сюда или кликните для выбора</p><input type="file" name="image" id="fileElem" class="d-none" accept="image/*"><button type="button" class="btn btn-primary" onclick="document.getElementById('fileElem').click();">Выбрать файл</button><div id="preview" class="mt-3"><?php if(!empty($p['image'])): ?><img src="uploads/<?= htmlspecialchars($p['image']) ?>" style="max-height:160px"><?php endif; ?></div></div></div><div class="col-12"><button class="btn btn-primary">Сохранить</button></div></form></div><script>const dropArea=document.getElementById('drop-area'); const fileInput=document.getElementById('fileElem'); const preview=document.getElementById('preview'); function showPreview(file){ const img=document.createElement('img'); img.style.maxHeight='160px'; img.src=URL.createObjectURL(file); preview.innerHTML=''; preview.appendChild(img);} dropArea.addEventListener('click',()=>fileInput.click()); dropArea.addEventListener('dragover',e=>{e.preventDefault(); dropArea.classList.add('dragover');}); dropArea.addEventListener('dragleave',()=>dropArea.classList.remove('dragover')); dropArea.addEventListener('drop',e=>{e.preventDefault(); dropArea.classList.remove('dragover'); const f=e.dataTransfer.files[0]; if(f){ fileInput.files=e.dataTransfer.files; showPreview(f);} }); fileInput.addEventListener('change',()=>{ if(fileInput.files[0]) showPreview(fileInput.files[0]); });</script><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script></body></html>